  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C25", "C01", "C09", "C23", "C149", "C140", "C188", "C201", "C196"],
  "contradictory_card_ids": ["C80", "C223", "C199", "C200"],
  "prediction_basis_card_ids": ["C25", "C01", "C09", "C23", "C149", "C140", "C188"],
  "claims": [
    {
      "claim": "All L1 gold-context records for the most transferable ester/amine and related chemotypes are above the 20% threshold: pethidine normal F 0.48 (C25), benazepril 28–37% (C01), delapril >55% (C09), neotame ≥34.3% (C23).",
      "card_ids": ["C25", "C01", "C09", "C23"]
    },
    {
      "claim": "L4 permeability evidence supports favorable intestinal absorption for the methyl-ester/amine chemotype: methylphenidate MDCK Papp 24.7×10^-6 cm/s (C149); neotame is rapidly absorbed with presystemic metabolism yet retains ≥34.3% systemic availability (C140, C23).",
      "card_ids": ["C149", "C140", "C23"]
    },
    {
      "claim": "L5 gut-wall evidence for thiophene-amine and chlorophenyl-ester-amine chemotypes shows high permeability without net efflux: ulotaront Papp 22–27×10^-6 cm/s with ER 1.1–1.3 (C188); amlodipine ER 1.14 (C201); lacosamide ER <1.5 (C196).",
      "card_ids": ["C188", "C201", "C196"]
    },
    {
      "claim": "The only negative mechanistic L5 card (felodipine as intestinal CYP3A substrate, C223) is for a different DHP scaffold and does not quantify F; mechanism alone is insufficient to establish F<20%.",
      "card_ids": ["C223"]
    },
    {
      "claim": "No direct query F measurement exists; the high prediction rests on convergent transferable human F records and permeability/efflux evidence, with unresolved uncertainty about ester hydrolysis.",
      "card_ids": ["C01", "C09", "C23", "C25", "C149", "C188"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C188", "C201", "C196", "C223"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule.",
    "No matched oral-versus-IV exposure data for the query itself.",
    "No query-specific esterase (CES1) or first-pass metabolism data.",
    "No query-specific intestinal P-gp/CYP3A measurement; L5 cards are for other chemotypes.",
    "Human ester-prodrug F records (benazepril, delapril) may reflect active-metabolite F rather than parent F.",
    "The extent of ester hydrolysis for clopidogrel-like methyl esters is not quantified in the supplied records."
  ],
  "decision_summary": "Keep high and strengthen: L5 gut-wall evidence adds supportive high-permeability/no-efflux data for thiophene-amine and chlorophenyl-ester-amine chemotypes (ulotaront, amlodipine, lacosamide), while the only negative mechanistic card (felodipine intestinal CYP3A) is for a different scaffold and does not quantify F. Combined with human ester/amine F records (pethidine 48%, benazepril 28–37%, delapril >55%, neotame ≥34.3%) and L4 permeability evidence, F≥20% remains better supported; no affirmative low evidence."
}

